<?php
declare(strict_types=1);
function report_complete_order(array $r):bool {return trim($r['customer']??'')!==''&&trim($r['phone']??'')!==''&&trim($r['address']??'')!==''&&mkt_number($r['money']??'')!==null&&trim($r['text']??'')!=='';}
function report_unified_core(PDO $db,array $input,array $catalog,array $board):array {
 $kind=(string)($input['product_kind']??'all');if($kind!=='all')$board['rows']=array_values(array_filter($board['rows'],static fn($r)=>product_row_kind($catalog,$r)===$kind));$range=report_range($input);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$input['campaign']='';$mkt=mkt_report($db,$input,$board,$catalog);$profit=mkt_profit_days($db,$input,$board,$catalog);
 $empty=static fn()=>['orders'=>0,'created'=>0,'sent'=>0,'sales'=>0.0,'salesKnown'=>true];$counts=['total'=>$empty(),'Nam'=>$empty(),'Nữ'=>$empty(),'unknown'=>$empty()];$products=[];$unresolvedOrders=0;
 foreach($board['rows'] as $r){if(!$r['date']||$r['date']<$range['from']||$r['date']>$range['to'])continue;$items=array_values(array_filter($r['items'],static fn($i)=>$sku===''||$i['sku']===$sku));if($sku!==''&&!$items)continue;$g=in_array($r['gender'],['Nam','Nữ'],true)?$r['gender']:'unknown';$complete=report_complete_order($r);$money=mkt_number($r['money']);$allocation=$complete&&!empty($r['valid'])&&$r['items']?mkt_allocate_revenue($r['items'],$money,$catalog):null;if($complete&&empty($r['valid']))$unresolvedOrders++;if($complete&&!$r['items'])$allocation=[''=>$money];
 foreach(['total',$g] as $key){if($complete){$counts[$key]['orders']++;$sale=$sku===''?$money:($allocation[$sku]??null);if($sale===null)$counts[$key]['salesKnown']=false;else $counts[$key]['sales']+=$sale;}if($r['created'])$counts[$key]['created']++;}
 foreach(($items?array_unique(array_column($items,'sku')):['']) as $code){$products[$code]??=['sku'=>$code]+$empty();if($complete){$products[$code]['orders']++;if($allocation===null)$products[$code]['salesKnown']=false;else $products[$code]['sales']+=$allocation[$code]??0;}if($r['created'])$products[$code]['created']++;}}

 foreach(stock_flow($db,$board['rows'])['outcomes'] as $o){$r=$o['row'];if(!$r['date']||$r['date']<$range['from']||$r['date']>$range['to'])continue;foreach($r['items'] as $i){if($sku!==''&&$sku!==$i['sku'])continue;$g=$catalog[$i['sku']]['gender']??$r['gender'];$g=in_array($g,['Nam','Nữ'],true)?$g:'unknown';$counts['total']['sent']+=$i['qty'];$counts[$g]['sent']+=$i['qty'];$products[$i['sku']]??=['sku'=>$i['sku']]+$empty();$products[$i['sku']]['sent']+=$i['qty'];}}
 $pgroup=[];foreach(['Nam','Nữ','unknown'] as $g)$pgroup[$g]=['revenue'=>0.0,'goods'=>0.0,'missing'=>false,'known'=>true];foreach($profit['products'] as $p){$g=$catalog[$p['sku']]['gender']??'';$g=in_array($g,['Nam','Nữ'],true)?$g:'unknown';$pgroup[$g]['revenue']+=$p['revenue'];$pgroup[$g]['goods']+=$p['goods'];$pgroup[$g]['missing']=$pgroup[$g]['missing']||!empty($p['missingCost']);$pgroup[$g]['known']=$pgroup[$g]['known']&&$p['revenueKnown'];$products[$p['sku']]??=['sku'=>$p['sku']]+$empty();$products[$p['sku']]['profit']=$p['profit'];}
 $groups=[];foreach(['total','Nam','Nữ','unknown'] as $g){$ads=$mkt['groups'][$g==='unknown'?'unclassified':$g];$p=$g==='total'?$profit['total']:null;$groups[$g]=$counts[$g]+['spend'=>$ads['spend'],'adsPurchases'=>$ads['ordersComplete']?$ads['adsOrders']:null,'adsCpa'=>$ads['ordersComplete']&&$ads['adsOrders']>0?$ads['spend']/$ads['adsOrders']:null,'realCpa'=>$mkt['hasData']&&$counts[$g]['orders']>0?$ads['spend']/$counts[$g]['orders']:null,'revenue'=>$p?($p['revenueKnown']?$p['revenue']:null):($pgroup[$g]['known']?$pgroup[$g]['revenue']:null),'goods'=>$p?(!$p['missingCost']?$p['goods']:null):(!$pgroup[$g]['missing']?$pgroup[$g]['goods']:null),'profit'=>$p?$p['profit']:($ads['rows']&&$pgroup[$g]['known']&&!$pgroup[$g]['missing']?$pgroup[$g]['revenue']-$ads['spend']-$pgroup[$g]['goods']:null)];}
 foreach($mkt['products'] as $p){$products[$p['sku']]??=['sku'=>$p['sku']]+$empty();$products[$p['sku']]+=['spend'=>$p['spend'],'adsPurchases'=>$p['ordersComplete']?$p['adsOrders']:null,'adsCpa'=>$p['ordersComplete']&&$p['adsOrders']>0?$p['spend']/$p['adsOrders']:null,'realCpa'=>($products[$p['sku']]['orders']??0)>0?$p['spend']/$products[$p['sku']]['orders']:null];}
 foreach($groups as &$g){if(!$g['salesKnown'])$g['sales']=null;$g['spendSalesPercent']=$g['sales']>0?$g['spend']/$g['sales']*100:null;}unset($g);foreach($products as &$p){$types=array_unique([product_sku_kind($catalog,$p['sku'],$range['from']),product_sku_kind($catalog,$p['sku'],$range['to'])]);$p['kind']=count($types)===1?reset($types):'changed';if(!$p['salesKnown'])$p['sales']=null;$p['spendSalesPercent']=$p['sales']>0&&isset($p['spend'])?$p['spend']/$p['sales']*100:null;}unset($p);
 usort($products,static fn($a,$b)=>($b['spend']??0)<=>($a['spend']??0));return ['unresolvedOrders'=>$unresolvedOrders,'reconciliation'=>mkt_reconciliation($db,$range),'range'=>$range,'groups'=>$groups,'products'=>array_values($products),'campaigns'=>$mkt['campaigns'],'daily'=>$profit['daily'],'costs'=>$profit['costs'],'catalog'=>array_values($catalog),'hasAds'=>$mkt['hasData'],'missingCost'=>$profit['total']['missingCost'],'notice'=>$profit['notice']];
}

function report_unified(PDO $db,array $input):array {
 $kind=(string)($input['product_kind']??'all');if(!in_array($kind,['all','test','normal','mixed','unclassified'],true))throw new RuntimeException('Loại sản phẩm không hợp lệ.',400);
 $catalog=board_catalog($db);$board=board_rows($db,$catalog);$result=report_unified_core($db,$input,$catalog,$board);$result['productKind']=$kind;$result['segments']=[];
 foreach(['normal','test','mixed','unclassified'] as $type){$part=$type===$kind?$result:report_unified_core($db,array_replace($input,['product_kind'=>$type]),$catalog,$board);$result['segments'][$type]=$part['groups']['total'];unset($part);}
 return $result;
}
